// HasMigration applies the HasEdge predicate on the "migration" edge.
func HasMigration() predicate.MigrationExecution {
	return predicate.MigrationExecution(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, MigrationTable, MigrationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasMigrationWith applies the HasEdge predicate on the "migration" edge with a given conditions (other predicates).
func HasMigrationWith(preds ...predicate.Migration) predicate.MigrationExecution {
	return predicate.MigrationExecution(func(s *sql.Selector) {
		step := newMigrationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

