// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MigrationExecution) predicate.MigrationExecution {
	return predicate.MigrationExecution(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MigrationExecution) predicate.MigrationExecution {
	return predicate.MigrationExecution(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MigrationExecution) predicate.MigrationExecution {
	return predicate.MigrationExecution(sql.NotPredicates(p))
}
